window.__votdWeek && window.__votdWeek({"week":"2028-06-19","reading":"Alma 13–16","days":[{"d":"2028-06-19","ref":"Alma 13:14","b":"Alma","c":13,"v":14,"he":"הֵן הִכָּנְעוּ כָּעָם בִּימֵי מַלְכִּי־צֶדֶק אֲשֶׁר הָיָה גַם־הוּא כֹּהֵן גָּדוֹל עַל־פִּי הַדִּבְרָה הַזֹּאת אֲשֶׁר דִּבַּרְתִּי אֲשֶׁר גַם־הוּא נָשָׂא עָלָיו אֶת־הַכְּהֻנָּה הַגְּדוֹלָה לְעוֹלָם׃","en":"Yea, humble yourselves even as the people in the days of Melchizedek, who was also a high priest after this same order which I have spoken, who also took upon him the high priesthood forever."},{"d":"2028-06-20","ref":"Alma 13:29","b":"Alma","c":13,"v":29,"he":"בֹּטְחִים בַּיהוָה מְיַחֲלִים לְחַיֵּי עוֹלָם נֹשְׂאִים אַהֲבַת אֱלֹהִים תָּמִיד בִּלְבַבְכֶם לְמַעַן תִּנָּשְׂאוּ בַּיּוֹם הָאַחֲרוֹן וְתָבֹאוּ אֶל־מְנוּחָתוֹ׃","en":"Having faith on the Lord; having a hope that ye shall receive eternal life; having the love of God always in your hearts, that ye may be lifted up at the last day and enter into his rest."},{"d":"2028-06-21","ref":"Alma 14:1","b":"Alma","c":14,"v":1,"he":"וַיְהִי כְּכַלּוֹתוֹ לְדַבֵּר אֶל־הָעָם וַיַּאֲמִינוּ רַבִּים מֵהֶם בִּדְבָרָיו וַיָּחֵלּוּ לָשׁוּב וְלִדְרֹשׁ אֶת־הַכְּתוּבִים׃","en":"And it came to pass after he had made an end of speaking unto the people many of them did believe on his words, and began to repent, and to search the scriptures."},{"d":"2028-06-22","ref":"Alma 14:3","b":"Alma","c":14,"v":3,"he":"וַיִּקְצְפוּ גַם עַל־אַלְמָא וַעֲמוּלֶק וּבַעֲבוּר הֵעִידוּ בְנֹכַח נֶגֶד רִשְׁעָתָם וַיְבַקְשׁוּ לַהֲמִיתָם בַּסֵּתֶר׃","en":"And they were also angry with Alma and Amulek; and because they had testified so plainly against their wickedness, they sought to put them away privily."},{"d":"2028-06-23","ref":"Alma 15:10","b":"Alma","c":15,"v":10,"he":"וְאָז קָרָא אַלְמָא אֶל־יְהוָה לֵאמֹר יְהוָה אֱלֹהֵינוּ רַחֵם עַל־הָאִישׁ הַזֶּה וּרְפָאֵהוּ כֶּאֱמוּנָתוֹ בַּמָּשִׁיחַ׃","en":"And then Alma cried unto the Lord, saying: O Lord our God, have mercy on this man, and heal him according to his faith which is in Christ."},{"d":"2028-06-24","ref":"Alma 16:14","b":"Alma","c":16,"v":14,"he":"וּלְכׇל־אֲשֶׁר שָׁמְעוּ אֶת־דִּבְרֵיהֶם נָתְנוּ אֶת־דְּבַר־אֱלֹהִים בְּלִי מַשּׂוֹא פָנִים תָּמִיד׃","en":"And as many as would hear their words, unto them they did impart the word of God, without any respect of persons, continually."},{"d":"2028-06-25","ref":"Alma 16:20","b":"Alma","c":16,"v":20,"he":"וְרַבִּים מִן־הָעָם שָׁאֲלוּ עַל־הַמָּקוֹם אֲשֶׁר יָבוֹא שָׁמָּה בֶּן־אֱלֹהִים וַיְלַמְּדוּ אוֹתָם כִּי יֵרָאֶה אֲלֵיהֶם אַחֲרֵי תְּחִיָּתוֹ וְאֶת־זֹאת שָׁמַע הָעָם בְּשִׂמְחָה וְגִילָה רַבָּה׃","en":"And many of the people did inquire concerning the place where the Son of God should come; and they were taught that he would appear unto them after his resurrection; and this the people did hear with great joy and gladness."}]});
